{
  "core_question": "How should a US-based clinical-stage biotech structure and value a co-development/co-commercialization deal with an EU pharma for a Phase 3 oncology asset, addressing clinical risk, regulatory/IP exposure, and financial economics?",
  "rationale": "The question spans clinical program assessment (healthcare), jurisdictional IP and regulatory structuring (legal), and valuation/milestone economics (finance).",
  "routes": ["healthcare", "legal", "finance"],
  "sub_questions": {
    "healthcare": "What are the primary clinical‑program risks for a single Phase 3 oncology asset seeking FDA accelerated approval, how can these risks be quantified for valuation purposes, and what mitigation strategies should be considered?",
    "legal": "How should the territorial rights split (US to the biotech, EU/UK to the pharma) be legally structured to protect IP exposure across jurisdictions, taking into account FDA accelerated‑approval requirements, EMA approvals, post‑Brexit UK regulations, and potential regulatory changes?",
    "finance": "What is a recommended approach for calculating rNPV and calibrating milestone payments in this co‑development deal, including upfront fees, tiered royalties, and the impact of territorial rights split on cash‑flow projections?"
  },
  "requires_recency_disclosure": true,
  "recency_notes": "Potentially stale items: FDA accelerated‑approval guidance updates post‑2024, EMA regulatory changes, UK post‑Brexit pharmaceutical regulations, recent IP litigation trends affecting oncology assets."
}
